const paths = [
"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivRepAffKit.lean",
"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivRepKit.lean",
"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivRepPullAt.lean",
"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivRepClassifyZ.lean"
];
const rs=await Promise.all(paths.map(p=>tools.exec_command({cmd:`sed -n '1,360p' '${p}'`,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:40000})));
for(let i=0;i<rs.length;i++) text(`===== ${paths[i]} =====\n${rs[i].output}`);

const results = await Promise.all([
  tools.exec_command({cmd:"rg -n -i \"represent|divRep|certificate|U1|U2|saturation|Grassmann|Picard\" MainProjects SubProjects -g '*.lean' | head -300",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:30000}),
  tools.exec_command({cmd:"find MainProjects -maxdepth 3 -type f | sort | head -200",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:20000}),
  tools.exec_command({cmd:"find SubProjects -maxdepth 3 -type f -name '*.lean' | sort | sed -n '1,240p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:24000}),
  tools.exec_command({cmd:"$HORIZON_GIT status --short",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:12000})
]); results.forEach((r,i)=>{text(`---${i+1}---\n${r.output}`)});
